$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
$root=Split-Path $PSScriptRoot -Parent
$path=Join-Path $root 'Chapter 3.docx'
$backup=Join-Path $root ('Review Backups/context-explanation-'+(Get-Date -Format yyyyMMdd-HHmmss))
New-Item -ItemType Directory -Path $backup -Force|Out-Null
Copy-Item -LiteralPath $path -Destination (Join-Path $backup 'Chapter 3.docx')
$work=Join-Path $backup 'Chapter 3 working.docx';Copy-Item -LiteralPath $path -Destination $work
$z=[IO.Compression.ZipFile]::Open($work,'Update')
try{
 $entry=$z.GetEntry('word/document.xml');$reader=[IO.StreamReader]::new($entry.Open());$d=[xml]$reader.ReadToEnd();$reader.Dispose()
 $w='http://schemas.openxmlformats.org/wordprocessingml/2006/main';$n=[Xml.XmlNamespaceManager]::new($d.NameTable);$n.AddNamespace('w',$w)
 function Txt($p){($p.SelectNodes('.//w:t',$n)|ForEach-Object InnerText)-join ''}
 $body=$d.SelectSingleNode('//w:body',$n)
 $caption=@($body.SelectNodes('w:p',$n)|Where-Object {(Txt $_).Trim() -match '^Figure 2\.'})
 $next=@($body.SelectNodes('w:p',$n)|Where-Object {(Txt $_).Trim() -eq 'Data Flow Diagram'})
 if($caption.Count -ne 1 -or $next.Count -ne 1){throw 'Ambiguous context section boundary'}
 $old=[Collections.Generic.List[object]]::new();$node=$caption[0].NextSibling
 while($node -and -not [object]::ReferenceEquals($node,$next[0])){if($node.LocalName -ne 'p' -or $node.SelectSingleNode('.//w:drawing',$n)){throw 'Unexpected non-explanation content'};$old.Add($node);$node=$node.NextSibling}
 if(-not $node -or $old.Count -lt 5){throw 'Context discussion not found'}
 $template=@($old|Where-Object {(Txt $_).Trim()})[0]
 $texts=@(
 'Figure 2 defines the external boundary of the IronGrind Membership and Operations Management System using a Gane-Sarson context diagram. Process 0 represents the system as a single unit, while the rectangles identify its three external user groups: Member / Applicant, Administrator, and Authorized Staff. Each directed arrow describes information entering or leaving the system. An arrow pointing toward Process 0 represents submitted data or a request; an arrow pointing toward an external entity represents information or a result returned to that user group. The diagram provides an overview of responsibilities and information exchange, rather than the sequence of screens, database operations, or implementation steps.',
 'The Member / Applicant entity combines two stages of the customer relationship: a person applying for membership and an existing member using personal account services. Its incoming flow consists of credentials, registration details, renewal requests, and permitted profile changes. Registration details describe the information submitted for review; submission alone does not mean that membership has been approved. A renewal request concerns an existing membership and must be reviewed before its result is applied. Permitted profile changes concern the signed-in member''s own editable personal information and do not include authority to approve requests, alter product stock, record sales, or modify another member''s account.',
 'The corresponding outgoing flow returns sign-in and application results, the member''s own membership information and QR code, attendance history, and the active product catalog. Access results indicate whether account access is permitted, while application results communicate the recorded review status. Membership information enables the member to check the plan, status, and applicable membership dates. The QR code supports identification during an authorized operator''s attendance scan; showing the QR code does not give the member attendance-recording privileges. Attendance history is limited to the member''s own visits. The catalog allows products to be viewed, while product-sale entries are handled through the administrator or authorized staff workflow rather than through a member checkout process.',
 'The Administrator entity exchanges information required for overall membership and operational supervision. Its incoming flow groups review decisions, membership operations, inventory updates, staff controls, phone-pairing controls, report queries, and activity-log queries. Review decisions approve or reject submitted applications and renewal requests. Membership operations cover supported counter registration, renewal, and plan-change actions. Inventory updates maintain product information and stock, while staff controls administer supported staff-account states. Pairing controls govern the mobile attendance scanner arrangement. Report and log queries request recorded information for review; requesting a report or reading a log is distinct from performing the operation described in those records. The grouped labels summarize related exchanges and do not imply that all inputs must be submitted together.',
 'The Administrator''s outgoing flow returns member records, operation results, staff states, pairing status, filtered activity logs, and reports. These outputs allow the administrator to confirm an operation, inspect the relevant account or membership state, monitor paired scanning devices, and examine operational information. Access to a member''s personal profile is read-only in the implemented administrator workflow. Approval, renewal, and plan changes are authorized membership operations and should not be interpreted as permission to edit the member''s personal profile fields. The context diagram therefore describes the administrator''s operational scope while the detailed process discussion explains the individual permissions and validation rules.',
 'The Authorized Staff entity exchanges credentials, counter details, request-review decisions, QR scans, and product-sale entries. After staff identity and active-account status have been verified, the permitted tasks include walk-in member registration, limited member lookup for counter transactions, direct renewal, active-member plan changes, review of online registration and renewal requests, attendance scanning, and product-sale recording. A member lookup supplies the limited details needed to select the correct person for an authorized transaction; it is not general access to the member''s personal profile. Staff review decisions are based on the request information made available by the staff interface. The QR scan flow submits a member identifier for the system to validate and record the applicable attendance result.',
 'The system returns staff access results, pending-request information or status, counter-operation results, scan results, permitted attendance records, and the staff operator''s own product-sale records. These outputs support the assigned task and allow its result to be checked. Staff access does not include viewing or editing existing member profiles, maintaining inventory, administering staff accounts or phone pairings, or opening administrator reports and activity logs. The narrower staff outputs distinguish the staff workspace from the administrator workspace even when both roles can initiate a supported membership or attendance operation. The diagram represents these information exchanges; authentication, role checks, database policies, and authorized functions enforce the access boundaries in the implementation.',
 'Walk-in customers are not drawn as a separate direct system user because an administrator or authorized staff operator enters their counter transactions. The customer supplies the relevant details to that operator, who submits the supported system entry and receives its confirmation. A saved sale or membership transaction is an internal operational record; the confirmation does not establish that the system issues a customer receipt. Likewise, the context diagram''s arrows represent information exchange rather than a physical payment channel, an online payment gateway, or the transfer of goods.',
 'All three external entities communicate with Process 0; the diagram does not show direct data flows between the actors. Internal data stores, authentication implementation details, and individual subprocesses are omitted at this level so that the system boundary remains clear. The Level 1 Data Flow Diagram expands the same system into the processes that authenticate users, review applications and renewals, perform membership and attendance operations, maintain inventory, record sales, generate reports, and retrieve activity logs. The ERD and data dictionary then describe how the resulting information is structured and stored. Read together, these models explain the external information requirements, internal processing responsibilities, and persistent data design without treating the context diagram as a procedural flowchart.'
 )
 foreach($text in $texts){
  $p=$template.CloneNode($true)
  foreach($bookmark in @($p.SelectNodes('.//w:bookmarkStart|.//w:bookmarkEnd',$n))){$null=$bookmark.ParentNode.RemoveChild($bookmark)}
  $ts=$p.SelectNodes('.//w:t',$n);$ts[0].InnerText=$text;foreach($t in @($ts|Select-Object -Skip 1)){$t.InnerText=''}
  $indent=$p.SelectSingleNode('w:pPr/w:ind',$n);if($indent){$null=$indent.SetAttribute('firstLine',$w,'720')}
  $null=$body.InsertBefore($p,$next[0])
 }
 foreach($p in $old){$null=$body.RemoveChild($p)}
 $stream=$entry.Open();$stream.SetLength(0);$writer=[IO.StreamWriter]::new($stream,[Text.UTF8Encoding]::new($false));try{$d.Save($writer)}finally{$writer.Dispose()}
}finally{$z.Dispose()}
$lock=[IO.File]::Open($path,'Open','ReadWrite','None');$lock.Dispose()
Copy-Item -LiteralPath $work -Destination $path -Force
"Replaced the context discussion with nine detailed paragraphs. Diagram, ERD, dictionary and other sections retained. Backup: $backup"
